import{_ as o,o as t,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Expenses — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Expenses — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/expenses"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Expenses — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/expenses"}]]},"headers":[],"relativePath":"deployment/expenses.md","filePath":"deployment/expenses.md","lastUpdated":1786664531000}'),n={name:"deployment/expenses.md"};function r(i,e,d,c,l,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="expenses-—-production-guide" tabindex="-1">Expenses — Production Guide <a class="header-anchor" href="#expenses-—-production-guide" aria-label="Permalink to &quot;Expenses — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>expenses</code></li><li>Category: <code>purchasing</code> (<strong>Purchasing</strong>), <code>category_sort_order = 40</code>, <code>sort_order = 30</code></li><li><strong>Free Marketplace opt-in</strong> module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code></li><li><strong>No hard module dependency</strong> — Expenses installs standalone; Vendors and Purchase Orders are optional soft links, only offered in the UI (and only validated) when already entitled</li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> by default; enable Expenses from Marketplace at any time, independent of Vendors / Purchase Orders</li><li>Existing workspaces that already have Expenses keep their subscription</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong> only)</li><li>Operators enable <strong>Expenses</strong> from Marketplace whenever needed — no prerequisite modules</li><li>Tenant permissions include <code>expenses.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li><li><code>purchase-orders.convert</code> ships alongside Expenses (same migration wave) so existing Purchase Orders installs can surface the convert action once Expenses is also enabled</li></ol><p>No stage or status seeder — expense status defaults to <code>draft</code> at creation time and advances via the state machine. Expense categories (Travel / Office / Software / Utilities / Other) are lazy-seeded on first category list, expense create, or PO convert — not via <code>db:seed</code>.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Expenses permissions (and <code>purchase-orders.convert</code>) for <strong>existing</strong> workspaces must ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="tenant-settings" tabindex="-1">Tenant settings <a class="header-anchor" href="#tenant-settings" aria-label="Permalink to &quot;Tenant settings&quot;">​</a></h2><p><code>expenses_number_prefix</code> (default <code>EXP-</code>) controls the auto-generated <code>number</code> prefix, same mechanism as <code>purchase_orders_number_prefix</code>. Updatable via <code>PUT /api/tenant/v1/settings</code>.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>expense_created</code>, <code>expense_updated</code>, <code>expense_deleted</code>, <code>expense_assigned</code>, <code>expense_status_changed</code>, <code>expense_note_added</code>, <code>expense_restored</code></li><li>Spatie activity log name <code>expense-categories</code> for category CRUD (lazy seed is quiet)</li><li>Notifications: assignment (mail + database) via <code>ExpenseAssignedNotification</code></li><li>Tenant mail settings with Central SMTP fallback</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate expense tables (<code>expenses</code>, <code>expense_notes</code>, <code>expense_activities</code>, <code>expense_categories</code>) and catalog bump <strong>1.0.0 → 1.1.0</strong> — <strong>before</strong> deploying the SPA (<code>category</code> string → <code>category_id</code> + embed)</li><li>Register the <code>expenses</code> catalog module (migration, not seeder) as free opt-in under the <code>purchasing</code> category — <strong>no</strong> <code>module_dependencies</code> row</li><li>Migrate the <code>purchase-orders.convert</code> permission and grant it to existing <code>admin</code>/<code>manager</code> roles</li><li>Confirm <code>module:expenses</code> + <code>expenses.*</code> permissions on target roles (category CRUD reuses the same permissions)</li><li>Deploy frontend (Expenses nav item under <strong>Purchasing</strong>, after Purchase Orders — list/form/detail + <strong>Manage categories</strong>; Convert to expense button on the Purchase Order detail sheet)</li><li>Smoke: create a <strong>new</strong> workspace → enable Expenses (alone, no other Purchasing modules) → Manage categories → create a custom category → create/edit/assign/note an expense → submit → approve → mark as paid → soft delete/restore</li><li>Smoke (soft convert): on a workspace with Vendors + Purchase Orders + Expenses all enabled → create a purchase order → send it → <strong>Convert to expense</strong> → confirm a draft expense with the PO&#39;s amount/vendor and <strong>Other</strong> category was created and the action is now hidden</li><li>Smoke (soft-gate off): on a workspace with Purchase Orders but <strong>without</strong> Expenses enabled → confirm the Convert button does not appear and the API returns a clear error if called directly</li></ol><h2 id="phase-4-roadmap-context" tabindex="-1">Phase 4 roadmap context <a class="header-anchor" href="#phase-4-roadmap-context" aria-label="Permalink to &quot;Phase 4 roadmap context&quot;">​</a></h2><p>Expenses is Milestone 3 (final) of <strong>Phase 4 Purchasing</strong>. Unlike Vendors → Purchase Orders (hard dependency chain), Expenses has no hard dependencies — Vendors and Purchase Orders links are soft/optional, and the Purchase-Order-to-Expense convert action is a soft cross-module integration (entitlement check at call time, not a <code>module_dependencies</code> row). This completes Phase 4. See <a href="/architecture/module-dependencies">module-dependencies.md</a> and <a href="/getting-started/product-roadmap">product-roadmap.md</a>.</p>',17)])])}const u=o(n,[["render",r]]);export{h as __pageData,u as default};
